```rust
fn ordered_tries(
    state: &GameState,
    seat: PlayerId,
    mut tries: Vec<ActionBody>,
    spread: bool,
    prices: &Prices,
) -> Vec<ActionBody> {
    if !spread {
        // Stable, so each aim keeps legal_actions order.
        tries.sort_by_key(|action| aim_of(state, seat, action));
        return tries;
    }
    let mut worths: Option<Vec<(&str, f64)>> = None;
    let mut ordered: Vec<ActionBody> = Vec::with_capacity(tries.len());
    let mut groups: Vec<PickGroup> = Vec::new();
    let mut picked: IndexSet<ActionBody> = IndexSet::new();
    let mut waiting: Vec<ActionBody> = Vec::new();
    let mut rest: Vec<ActionBody> = Vec::new();
    for action in tries {
        match aim_of(state, seat, &action) {
            Aim::SeatHero => ordered.push(action),
            Aim::Other => rest.push(action),
            Aim::SeatCard => {
                if !picked.insert(pick_of(&action)) {
                    waiting.push(action);
                    continue;
                }
                let table = worths.get_or_insert_with(|| {
                    active_units_of(state, seat)
                        .into_iter()
                        .map(|unit| (unit.id.as_str(), unit_worth(state, unit, &AI_EVAL, prices)))
                        .collect()
                });
                let worth = aimed_worth(table, &action);
                let source = source_of(&action);
                match groups.iter().position(|group| group.source == source) {
                    Some(at) => groups[at].picks.push((worth, action)),
                    None => groups.push(PickGroup { source, picks: vec![(worth, action)] }),
                }
            }
        }
    }
    for group in &mut groups {
        // Highest worth first; `sort_by` is stable, so equal worths keep legal_actions order.
        group.picks.sort_by(|a, b| b.0.total_cmp(&a.0));
    }
    let deepest = groups.iter().map(|group| group.picks.len()).max().unwrap_or(0);
    for round in 0..deepest {
        ordered.extend(groups.iter().filter_map(|group| group.picks.get(round)).map(|(_, pick)| pick.clone()));
    }
    ordered.extend(waiting);
    ordered.extend(rest);
    ordered
}
```

The worth table is built lazily, only once a seat-card try appears, so a step with no such try reads no `unit_view`.

